"use client";

import { useState } from "react";
import { Check, RotateCcw, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { action, panel, secondary } from "@/lib/takt-surface";

export function PredictOutput({
  code = 'console.log("UI-42".slice(3).length)',
  options = ["2", "3", "5"],
  answer = "2",
  explanation = "After slice(3), the remaining string \"42\" has length 2.",
  onAnswer,
  className,
}: {
  code?: string;
  options?: string[];
  answer?: string;
  explanation?: string;
  onAnswer?: (guess: string) => void;
  className?: string;
}) {
  const [guess, setGuess] = useState<string>();
  const [revealed, setRevealed] = useState(false);
  const correct = guess === answer;
  return (
    <section className={cn(panel, "grid w-72 max-w-full gap-3", className)}>
      <strong>What will this print?</strong>
      <pre tabIndex={0} className="overflow-x-auto rounded-lg bg-muted p-3 text-xs">
        <code>{code}</code>
      </pre>
      <div className="flex flex-wrap gap-1">
        {options.map((option) => (
          <button
            key={option}
            type="button"
            aria-pressed={guess === option}
            disabled={revealed}
            className="min-h-9 rounded-lg border px-3 font-mono text-xs aria-pressed:border-primary aria-pressed:bg-primary/10 motion-safe:transition-colors"
            onClick={() => setGuess(option)}
          >
            {option}
          </button>
        ))}
      </div>
      {revealed ? (
        <div className="grid gap-2 motion-safe:animate-in motion-safe:slide-in-from-bottom-1">
          <output className="grid gap-1">
            <strong className="flex items-center gap-2 text-sm">
              {correct ? <Check size={15} /> : <X size={15} />}
              {correct ? "Correct" : "Program output"}
              <code>{answer}</code>
            </strong>
            <span className="text-xs text-muted-foreground">{explanation}</span>
          </output>
          <button
            type="button"
            className={secondary}
            onClick={() => {
              setGuess(undefined);
              setRevealed(false);
            }}
          >
            <RotateCcw size={13} />
            Try again
          </button>
        </div>
      ) : (
        <button
          type="button"
          disabled={guess === undefined || !options.includes(guess)}
          className={action}
          onClick={() => {
            if (guess !== undefined) {
              setRevealed(true);
              onAnswer?.(guess);
            }
          }}
        >
          Check prediction
        </button>
      )}
    </section>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
